    if (new Set(n.pins.map(p=>p.id)).size!==n.pins.length) throw Error(`Duplicate pin IDs on ${n.name}.`);
    if (new Set(n.pinSections.map(s=>s.id)).size!==n.pinSections.length) throw Error(`Duplicate section IDs on ${n.name}.`);
