      if(n.pins.some(p=>p.section===child.id))continue;
      for(const name of ['PWM','V+','GND'])n.pins.push({id:uid(),section:child.id,name,type:name==='PWM'?'PWM':name==='GND'?'ground':'power',notes:''});
